-- ===== Retire les anciennes specialites (photo/video) des profils existants ===== a lancer UNE fois
update public.profiles set specialties = array(select x from unnest(specialties) as x where x in ('Girlfriend experience','Accompagnement','Dîner','Soirée','Week-end','Voyage','Massage','Massage tantrique','Relaxation','Sensuel','Câlin','Duo','Couple','Rôle play','Lingerie','Tenues sur demande','Strip-tease','Danse','Glamour','Élégante','Naturelle','Discrète','Complice','Fétichisme','Domination','Soumission','Pieds','Livecam','Sortie culturelle','Langues & conversation')) where specialties is not null;
